declare const tools: { mcp__githits__ask(args: {
  // Use `text` (default) for reading and tool follow-ups; it is token-efficient. Use `json` only to parse responses in code or obtain fields absent from text.
  format?: "text" | "json";
  // One question to answer from indexed public evidence. Do not include credentials, personal data, private code, or proprietary content.
  question: string;
  // Source pointer format. `mcp` returns directly callable code_read/docs_read calls; `url` returns original upstream HTTP URLs.
  source_format?: "mcp" | "url";
  // Optional canonical public OSS package or repository target, such as npm:express or github:expressjs/express. Omit target and thread_id to identify the target from the question.
  target?: string;
  // Thread UUID returned by an earlier ask call. Cannot be combined with target. Reuse a thread only when the prior answer is insufficient or additional information is needed.
  thread_id?: string;
}): Promise<CallToolResult>; };
```"},{"name":"mcp__githits__code_diff","description":"Experimental source diff between two explicit package versions or public repository refs for an already-canonical target. Pass `target` without a version or ref: either a compact string such as `npm:express` / `github:expressjs/express`, or one structured `{registry, package_name}` / `{repo_url}` object. Pass the endpoints separately as `from` and `to`. Package targets still return repository-wide diffs: sibling paths may appear, and a bounded result with no package paths does not prove the package unchanged. The default `name-status` view is bounded inventory; use `stat` for magnitude or `patch` for content. In `text`, patch previews are bounded at 320 UTF-8 bytes; use `format: "json"` for the exact full returned patch, still subject to `max_patch_bytes` and backend content coverage. Incomplete, filtered, byte-escaped, omitted, or unavailable patch evidence is not authoritative or safely applicable. Raw diffs never prove compatibility or upgrade safety. Do not include credentials, personal data, private code, or proprietary content in inputs.

