declare const tools: { mcp__githits__code_diff(args: {
  // Use `text` (default) for reading and tool follow-ups; it is token-efficient. Use `json` only to parse responses in code or obtain fields absent from text. Text patch previews are bounded at 320 UTF-8 bytes; JSON includes the full returned patch, still subject to backend limits and content coverage.
  format?: "text" | "json";
  // Required starting package version or public repository ref.
  from: string;
  // Optional relevance-ranked returned-file bound from 1 through 300.
  max_files?: number;
  // Optional aggregate patch-byte bound from 1024 through 2097152; patch view only.
  max_patch_bytes?: number;
  // Optional single non-empty repository-relative glob. Supports literals, `*`, `?`, whole-component `**`, and backslash escapes (for example `lib/**/*.js`); no braces, character classes, `!`, or Git pathspec magic.
  path_glob?: string;
  // One unversioned compact target string such as `npm:express` or `github:expressjs/express`, or an exact object `{registry, package_name}` / `{repo_url}`. Do not embed a version or ref.
  target: string | { package_name: string; registry: string; } | { repo_url: string; };
  // Required ending package version or public repository ref.
  to: string;
  // Projection: `name-status` (default, bounded inventory), `name-only`, `stat`, or `patch`. `max_patch_bytes` is valid only for `patch`.
  view?: "name-status" | "name-only" | "stat" | "patch";
}): Promise<CallToolResult>; };
```"},{"name":"mcp__githits__code_files","description":"List indexed files and paths in a public repo or package. Then use `code_read` or `code_grep`. Use this for enumeration tasks such as files under a directory; use `path_prefix` for directory prefixes (e.g. `lib/`) and optional `extensions` for language filtering. Discover paths before `code_read` when you don't yet know the path, or when it returns `FILE_NOT_FOUND`, `FILE_PATH_EXCLUDED`, or `SOURCE_FILE_INVENTORY_UNKNOWN`. Also use it to scope `code_grep`. Address via `target.registry` + `target.package_name` (package scope) or `target.repo_url` + optional `target.git_ref` (repo scope), mutually exclusive. Narrow with `path`, `path_prefix`, `globs`, `extensions`, `file_types`, `languages`, or file-intent filters. JSON envelope shape: `{total, hasMore, files: [{path, name, language, fileType, byteSize}], resolution, indexedVersion}`. When fresh data is not ready within the wait window, responses may include `targetResolution` provenance, `indexingEstimate`, and immediately-queryable alternatives. `availableVersions` and `availableRefs` are already indexed/queryable; `suggestedRefs` are fuzzy ref hints and may need indexing first. On an `INDEXING` error envelope, retry with a longer `wait_timeout_ms` or use a version/ref from `details.availableVersions` / `details.availableRefs`.

